/**
 * The furniture catalogue.
 *
 * These definitions are no longer hand-maintained. They are generated by the
 * Sprite Factory (tools/sprite-factory) alongside the sprites themselves, so an
 * item's footprint, collision box, interaction spots and artwork can never drift
 * apart - they come out of the same 3D model in one pass.
 *
 * To change a piece of furniture, edit tools/sprite-factory/src/catalog.ts and
 * run `npm run sprites`.
 */

import { FurnitureDefinition } from '../context/GameContext'
import generated from './furnitureDefinitions.generated.json'

export const FURNITURE_DEFINITIONS = generated as unknown as Record<string, FurnitureDefinition>

export const getFurnitureDefinition = (id: string): FurnitureDefinition | null => {
  return FURNITURE_DEFINITIONS[id] || null
}

export const getFurnitureByCategory = (category: FurnitureDefinition['category']): FurnitureDefinition[] => {
  return Object.values(FURNITURE_DEFINITIONS).filter(furniture => furniture.category === category)
}

export const getAllFurnitureDefinitions = (): FurnitureDefinition[] => {
  return Object.values(FURNITURE_DEFINITIONS)
}

/** Furniture that can only be placed on a wall or hung from the ceiling. */
export const getMountedFurniture = (): FurnitureDefinition[] => {
  return getAllFurnitureDefinitions().filter(furniture => furniture.placement && furniture.placement !== 'floor')
}
